//! Flash-friendly bring-up data shared byte-for-byte by Linux and embedded hosts.
//! The EPUB is generated by `scripts/prepare-sample-book.py`, not at runtime.
use nanofish::{StaticFile, StaticSite};

pub const OPDS_MEDIA_TYPE: &str = "application/opds+json";
pub const CATALOG: &[u8] = include_bytes!("../sample/catalog.json");
pub const BOOK: &[u8] = include_bytes!("../sample/connection-check.epub");

/// One OPDS 2.0 acquisition feed and an original-text EPUB. No allocator,
/// filesystem, database, or platform-specific networking is needed for the data.
pub static FILES: StaticSite<3> = StaticSite::new([
    StaticFile {
        path: "/",
        content_type: Some(OPDS_MEDIA_TYPE),
        body: CATALOG,
        etag: "\"sample-catalog-v1\"",
        gzip: None,
    },
    StaticFile {
        path: "/opds",
        content_type: Some(OPDS_MEDIA_TYPE),
        body: CATALOG,
        etag: "\"sample-catalog-v1\"",
        gzip: None,
    },
    StaticFile {
        path: "/books/connection-check.epub",
        content_type: Some("application/epub+zip"),
        body: BOOK,
        etag: "\"sample-book-v1\"",
        gzip: None,
    },
]);
